const rawAnalyzeData = $node["Extract National Id "].json.content.parts[0].text;

let newRequest = {};
try {
  newRequest = typeof rawAnalyzeData === 'string' ? JSON.parse(rawAnalyzeData) : rawAnalyzeData;
} catch (e) {
  newRequest = {};
}

// 2. قراءة الصفوف المرجعة من Google Sheets Search
const existingRows = $input.all();
const currentDate = new Date();

let duplicateApprovalsFound = [];

// 3. فحص الصفوف المرجعة مباشرة
for (const item of existingRows) {
  const row = item.json;

  // تجنب الصفوف الفارغة
  if (!row || Object.keys(row).length === 0) continue;

  // تنظيف حالة الموافقة
  const status = String(row.preauth_status || row.status || '').trim().toLowerCase();

  // معالجة تاريخ الانتهاء (لو مش مكتوب يفترض ساري)
  const expiryDate = row.expiry_date ? new Date(row.expiry_date) : null;
  const isNotExpired = expiryDate ? expiryDate >= currentDate : true;

  // فحص مرن وقوي لحالة الموافقة
  const isApprovedStatus = status.includes('موافق') || 
                           status.includes('مقبول') || 
                           status.includes('approved') ||
                           status.includes('مقبوله');

  // البحث عن الـ Drive File ID بأكثر من صيغة مسميات محتملة من الشيت
  const driveFileId = row.drive_file_id || 
                      row["drive_file_id"] || 
                      row["Drive File ID"] || 
                      row.file_id || 
                      '';

  // طالما النود بتاعة السيرش جابت الصف ده، والحالة مقبولة وسارية
  if (isApprovedStatus && isNotExpired) {
    duplicateApprovalsFound.push({
      approval_id: row.message_id || row.row_number || 'موافقة سارية',
      medication: row.requested_medication || newRequest.requested_medication || '',
      patient_name: row.patient_name || '',
      preauth_status: row.preauth_status || row.status,
      timestamp: row.timestamp || '',
      drive_file_id: driveFileId // الـ ID الصحيح للـ Drive File
    });
  }
}

// 4. تحديد سحب الـ binary المباشر من النود الرئيسية
const originalBinary = $node["Loop Over Items1"]?.binary || $node["Gmail Trigger"]?.binary || $input.item.binary;

// 5. إخراج النتيجة النهائية
const hasDuplicates = duplicateApprovalsFound.length > 0;

return [{
  json: {
    has_active_approval: hasDuplicates,
    approval_info: duplicateApprovalsFound,
    extracted_data: newRequest
  },
  binary: originalBinary
}];

